function showFeedback(){openPanel("📝 FEEDBACK",'<div class="feedback-box"><h2>Help de game verbeteren</h2><p>Een bug gevonden of een goed idee? Stuur het rechtstreeks naar <b>RAMZY</b>.</p><textarea id="feedbackText" maxlength="1000" placeholder="Schrijf hier je feedback..."></textarea><div class="small" style="margin:8px 0">Maximaal 1000 tekens</div><button class="action" onclick="sendFeedback()">📨 VERSTUUR NAAR RAMZY</button></div>'+(state.isAdmin?'<button class="action" style="margin-top:18px" onclick="showFeedbackInbox()">📥 BEKIJK FEEDBACK-INBOX</button>':""))}
async function sendFeedback(){const el=$("feedbackText"),message=el?el.value.trim():"";if(!message)return alert("Schrijf eerst je feedback.");try{const r=await fetch("/api/feedback",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({message})});const d=await r.json();if(!r.ok)throw new Error(d.error||"Versturen mislukt.");el.value="";alert("✅ Bedankt! Je feedback is naar RAMZY gestuurd.")}catch(e){alert(e.message)}}
async function showFeedbackInbox(){openPanel("📥 FEEDBACK VOOR RAMZY","<p>Feedback laden...</p>");try{const r=await fetch("/api/admin/feedback");const d=await r.json();if(!r.ok)throw new Error(d.error||"Laden mislukt.");openPanel("📥 FEEDBACK VOOR RAMZY",d.feedback.length?d.feedback.map(f=>'<div class="feedback-message"><b>👤 '+escapeHtml(f.username)+'</b><small>'+new Date(f.created_at).toLocaleString("nl-BE")+'</small><p>'+escapeHtml(f.message)+'</p></div>').join(""):'<p>Nog geen feedback ontvangen.</p>')}catch(e){openPanel("📥 FEEDBACK VOOR RAMZY","<p>"+escapeHtml(e.message)+"</p>")}}

async function showPrivateChats(){openPanel("🔒 Privéberichten",'<div class="chat-tabs"><button onclick="showChat()">🌍 ALGEMEEN</button><button class="active">🔒 PRIVÉ</button></div><p>Spelers laden...</p>');try{const r=await fetch("/api/private-chat/users"),d=await r.json();if(!r.ok)throw new Error(d.error||"Laden mislukt.");$("panelBody").innerHTML='<div class="chat-tabs"><button onclick="showChat()">🌍 ALGEMEEN</button><button class="active">🔒 PRIVÉ</button></div><p class="small">Kies een speler om privé te praten.</p><div class="private-users">'+d.users.map(u=>'<button onclick="openPrivateChat('+u.id+')"><span>👤</span><b>'+escapeHtml(u.username)+'</b><small>Privébericht sturen ›</small></button>').join("")+'</div>'}catch(e){$("panelBody").innerHTML="<p>"+escapeHtml(e.message)+"</p>"}}
async function openPrivateChat(id){openPanel("🔒 Privéchat","<p>Berichten laden...</p>");try{const r=await fetch("/api/private-chat/"+id),d=await r.json();if(!r.ok)throw new Error(d.error||"Laden mislukt.");openPanel("🔒 "+escapeHtml(d.username),'<div class="private-chat-note">🔒 Alleen jij en '+escapeHtml(d.username)+' kunnen deze berichten zien.</div><div id="privateMessages" class="private-messages">'+(d.messages.length?d.messages.map(m=>'<div class="private-msg '+(m.sender_name===state.name?'mine':'theirs')+'"><b>'+escapeHtml(m.sender_name)+'</b><p>'+escapeHtml(m.message)+'</p><small>'+new Date(m.created_at).toLocaleTimeString("nl-BE",{hour:"2-digit",minute:"2-digit"})+'</small></div>').join(""):'<p class="small">Nog geen berichten. Zeg hallo!</p>')+'</div><div class="private-send"><input id="privateInput" maxlength="500" placeholder="Schrijf een privébericht..."><button onclick="sendPrivateChat('+id+')">STUUR</button></div><button class="private-back" onclick="showPrivateChats()">← Terug naar spelers</button>');const b=$("privateMessages");if(b)b.scrollTop=b.scrollHeight}catch(e){openPanel("🔒 Privéchat","<p>"+escapeHtml(e.message)+"</p>")}}
async function sendPrivateChat(id){const el=$("privateInput"),message=el?el.value.trim():"";if(!message)return;try{const r=await fetch("/api/private-chat/"+id,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({message})}),d=await r.json();if(!r.ok)throw new Error(d.error||"Versturen mislukt.");await openPrivateChat(id)}catch(e){alert(e.message)}}

async function showMyCity(){openPanel("🌃 ISOMETRIC WORLD V1","<p>Wereld laden...</p>");try{const r=await fetch("/api/my-city"),d=await r.json();if(!r.ok)throw new Error(d.error||"Wereld laden mislukt.");openPanel("🌃 ISOMETRIC WORLD V1",'<div class="iso-wrap"><div class="iso-status"><b>WEST-VLAMMERS CITY</b><span>ISOMETRIC ONLINE WORLD</span></div><div id="worldMap" class="iso-world"><div class="iso-floor"></div><div class="iso-road ir1"></div><div class="iso-road ir2"></div><div class="iso-building ihq"><div class="iso-roof"></div><div class="iso-front"><i></i><i></i><i></i><em></em></div><div class="iso-side"></div><b>MAFFIA HQ</b></div><div class="iso-building iapt"><div class="iso-roof"></div><div class="iso-front"><i></i><i></i><i></i><em></em></div><div class="iso-side"></div><b>APPARTEMENTEN</b></div><div class="iso-building iimmo"><div class="iso-roof"></div><div class="iso-front"><i></i><i></i><em></em></div><div class="iso-side"></div><b>IMMO</b></div><div class="iso-tree it1"><i></i></div><div class="iso-tree it2"><i></i></div><div class="iso-tree it3"><i></i></div><div id="worldPlayer" class="iso-avatar"><div class="iso-av-shadow"></div><div class="iso-av-head"></div><div class="iso-av-body"></div><div class="iso-av-leg l"></div><div class="iso-av-leg r"></div><b>'+escapeHtml(state.name||"JIJ")+'</b></div></div><div class="iso-pad"><button data-move="up">▲</button><button data-move="left">◀</button><button data-move="down">▼</button><button data-move="right">▶</button></div><div class="iso-note">Loop over de isometrische tegels · andere spelers verschijnen live</div></div>');setupIsoWorld()}catch(e){openPanel("🌃 ISOMETRIC WORLD V1","<p>"+escapeHtml(e.message)+"</p>")}}
let isoPos={x:50,y:70};function setupIsoWorld(){const p=$("worldPlayer"),map=$("worldMap");if(!p||!map)return;try{const q=JSON.parse(localStorage.getItem("isoPos")||"null");if(q)isoPos=q}catch(e){}const draw=()=>{p.style.left=isoPos.x+"%";p.style.top=isoPos.y+"%"};const step=(dx,dy)=>{isoPos.x=Math.max(7,Math.min(92,isoPos.x+dx));isoPos.y=Math.max(18,Math.min(91,isoPos.y+dy));draw();localStorage.setItem("isoPos",JSON.stringify(isoPos));fetch("/api/world/position",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(isoPos)}).catch(()=>{})};document.querySelectorAll(".iso-pad button").forEach(b=>b.onclick=()=>{const d=b.dataset.move;if(d==="up")step(0,-4);if(d==="down")step(0,4);if(d==="left")step(-5,0);if(d==="right")step(5,0)});draw();const sync=async()=>{if(!$("worldMap"))return;try{await fetch("/api/world/position",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(isoPos)});const r=await fetch("/api/world/players"),d=await r.json();if(!r.ok)return;const alive=new Set;for(const q of d.players||[]){if(String(q.user_id)===String(d.selfId))continue;const id="isoOther_"+q.user_id;alive.add(id);let el=$(id);if(!el){el=document.createElement("div");el.id=id;el.className="iso-avatar iso-other";el.innerHTML='<div class="iso-av-shadow"></div><div class="iso-av-head"></div><div class="iso-av-body"></div><div class="iso-av-leg l"></div><div class="iso-av-leg r"></div><b></b>';map.appendChild(el)}el.style.left=Number(q.pos_x)+"%";el.style.top=Number(q.pos_y)+"%";el.querySelector("b").textContent=q.username}map.querySelectorAll(".iso-other").forEach(x=>{if(!alive.has(x.id))x.remove()})}catch(e){}};sync();window._worldSync&&clearInterval(window._worldSync);window._worldSync=setInterval(sync,1500)}

let simulatorPending=null;
function startSimulatorBuild(key,name){simulatorPending={key,name};selectedCityBuilding=null;const h=$("simHint");if(h)h.innerHTML="📍 Tik nu op een vrije plek om <b>"+escapeHtml(name)+"</b> te bouwen.";const g=$("simBuildGhost");if(g)g.classList.remove("hidden")}
function setupSimulator(){const map=$("simMap");if(!map)return;map.addEventListener("click",async e=>{if(e.target.closest(".sim-building"))return;if(!simulatorPending&&!selectedCityBuilding)return;const r=map.getBoundingClientRect(),x=Math.max(8,Math.min(88,(e.clientX-r.left)/r.width*100)),y=Math.max(9,Math.min(88,(e.clientY-r.top)/r.height*100));if(simulatorPending){const p=simulatorPending;simulatorPending=null;try{const res=await fetch("/api/my-city/build",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({key:p.key,plot:0})}),d=await res.json();if(!res.ok)throw new Error(d.error||"Bouwen mislukt.");applyUser(d.user);await moveSimulatorBuilding(p.key,x,y);alert("🏗️ "+d.name+" gebouwd!")}catch(err){alert(err.message);showMyCity()}return}await moveSimulatorBuilding(selectedCityBuilding,x,y)})}
async function moveSimulatorBuilding(key,x,y){try{const res=await fetch("/api/my-city/move",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({key,x,y})}),d=await res.json();if(!res.ok)throw new Error(d.error||"Plaatsen mislukt.");selectedCityBuilding=null;showMyCity()}catch(e){alert(e.message)}}
let selectedCityBuilding=null,pendingCityBuild=null;
function startCityBuild(key,name){pendingCityBuild={key,name};selectedCityBuilding=null;document.querySelectorAll('.city-build-slot:not(.occupied)').forEach(x=>x.classList.add('ready'));alert('Kies nu een vrij + perceel voor '+name+'.')}

function selectCityBuilding(key){selectedCityBuilding=key;document.querySelectorAll(".city-building-piece").forEach(x=>x.classList.toggle("selected",x.dataset.cityKey===key));document.querySelectorAll(".city-build-slot").forEach(x=>x.classList.add("ready"))}
async function chooseCityPlot(i){if(pendingCityBuild)return buildCityBuilding(pendingCityBuild.key,i);return placeSelectedOnSlot(i)}
async function placeSelectedOnSlot(i){if(!selectedCityBuilding){alert("Tik eerst op het gebouw dat je wilt verplaatsen.");return}const slots=[[59.7,77.3],[44.8,86.0],[58.0,91.2],[43.0,98.0]],p=slots[i];try{const res=await fetch("/api/my-city/move",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({key:selectedCityBuilding,x:p[0],y:p[1]})}),d=await res.json();if(!res.ok)throw new Error(d.error||"Plaatsen mislukt.");selectedCityBuilding=null;showMyCity()}catch(e){alert(e.message)}}
function setupCityPlacement(){const world=document.querySelector(".city-world");if(!world)return;world.addEventListener("click",async e=>{if(!selectedCityBuilding||e.target.closest(".city-building-piece"))return;const r=world.getBoundingClientRect(),x=Math.max(4,Math.min(82,(e.clientX-r.left)/r.width*100)),y=Math.max(5,Math.min(78,(e.clientY-r.top)/r.height*100));const piece=document.querySelector('[data-city-key="'+selectedCityBuilding+'"]');if(piece){piece.style.left=x+"%";piece.style.top=y+"%"}try{const res=await fetch("/api/my-city/move",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({key:selectedCityBuilding,x,y})});const d=await res.json();if(!res.ok)throw new Error(d.error||"Opslaan mislukt.");selectedCityBuilding=null;document.querySelectorAll(".city-building-piece").forEach(z=>z.classList.remove("selected"))}catch(err){alert(err.message)}})}
async function buildCityBuilding(key,plot){if(!Number.isInteger(plot))return alert('Kies eerst een bouwperceel.');try{const r=await fetch("/api/my-city/build",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({key,plot})}),d=await r.json();if(!r.ok)throw new Error(d.error||"Bouwen mislukt.");applyUser(d.user);pendingCityBuild=null;alert("🏗️ "+d.name+" gebouwd!");showMyCity()}catch(e){alert(e.message)}}
async function upgradeCityBuilding(key){if(!confirm("Gebouw upgraden?"))return;try{const r=await fetch("/api/my-city/upgrade",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({key})}),d=await r.json();if(!r.ok)throw new Error(d.error||"Upgrade mislukt.");applyUser(d.user);showMyCity()}catch(e){alert(e.message)}}

async function collectCityIncome(){try{const r=await fetch("/api/my-city/collect",{method:"POST"}),d=await r.json();if(!r.ok)throw new Error(d.error||"Innen mislukt.");if(d.user)applyUser(d.user);alert("💰 €"+fmt(d.amount)+" stadsinkomen geïnd!");showMyCity()}catch(e){alert(e.message)}}

let v6Pos={x:50,y:55};
function setupV6Player(){const p=$("v6Player"),map=$("simMap");if(!p||!map)return;try{const q=JSON.parse(localStorage.getItem("v6Pos")||"null");if(q&&Number.isFinite(q.x)&&Number.isFinite(q.y))v6Pos=q}catch(e){}const draw=()=>{p.style.left=v6Pos.x+"%";p.style.top=v6Pos.y+"%"};const move=(dx,dy)=>{v6Pos.x=Math.max(4,Math.min(92,v6Pos.x+dx));v6Pos.y=Math.max(5,Math.min(92,v6Pos.y+dy));localStorage.setItem("v6Pos",JSON.stringify(v6Pos));draw()};draw();document.querySelectorAll(".v6-controls button").forEach(b=>{const go=()=>{const d=b.dataset.dir;if(d==="up")move(0,-3);if(d==="down")move(0,3);if(d==="left")move(-3,0);if(d==="right")move(3,0)};b.onclick=go});window._v6KeyHandler&&document.removeEventListener("keydown",window._v6KeyHandler);window._v6KeyHandler=e=>{const k=e.key.toLowerCase();if(["arrowup","w"].includes(k)){e.preventDefault();move(0,-2)}else if(["arrowdown","s"].includes(k)){e.preventDefault();move(0,2)}else if(["arrowleft","a"].includes(k)){e.preventDefault();move(-2,0)}else if(["arrowright","d"].includes(k)){e.preventDefault();move(2,0)}};document.addEventListener("keydown",window._v6KeyHandler)}


