function setupV5(){
 const cv=$("v5canvas");if(!cv)return;const g=cv.getContext("2d"),D=devicePixelRatio||1,TW=64,TH=32,S=24;
 let W,H,me={x:12,y:14,tx:12,ty:14},others=[],time=0;
 const bs=[{x:3,y:3,w:4,h:3,z:78,n:"MAFFIA HQ",go:"missions",c:["#293542","#18222c","#3c4b59"]},{x:15,y:3,w:4,h:3,z:66,n:"NIGHTCLUB",go:"chat",c:["#602873","#341642","#88369d"]},{x:2,y:15,w:4,h:4,z:92,n:"APPARTEMENTEN",go:"properties",c:["#31576c","#203846","#4e8096"]},{x:16,y:15,w:4,h:4,z:82,n:"ZIEKENHUIS",go:"hospital",c:["#b9d0d3","#70878b","#e3eeee"]},{x:9,y:17,w:4,h:3,z:58,n:"GARAGE",go:"garage",c:["#4e3b50","#2c2532","#735a76"]},{x:17,y:9,w:3,h:3,z:62,n:"POLITIE",go:"players",c:["#315c83","#19354f","#4d81aa"]}];
 function resize(){let r=cv.parentElement.getBoundingClientRect();W=r.width;H=Math.max(570,Math.min(720,innerHeight*.7));cv.style.width=W+"px";cv.style.height=H+"px";cv.width=W*D;cv.height=H*D;g.setTransform(D,0,0,D,0,0)}
 function cam(){let p=raw(me.x,me.y);return{x:W/2-p.x,y:H*.55-p.y}}
 function raw(a,b){return{x:(a-b)*TW/2,y:(a+b)*TH/2}}
 function iso(a,b){let p=raw(a,b),q=cam();return{x:p.x+q.x,y:p.y+q.y}}
 function diamond(p,fill,stroke){g.beginPath();g.moveTo(p.x,p.y-TH/2);g.lineTo(p.x+TW/2,p.y);g.lineTo(p.x,p.y+TH/2);g.lineTo(p.x-TW/2,p.y);g.closePath();g.fillStyle=fill;g.fill();if(stroke){g.strokeStyle=stroke;g.stroke()}}
 function tile(i,j){let road=i===11||i===12||j===11||j===12,p=iso(i,j);diamond(p,road?"#353d43":((i+j)%2?"#47765b":"#4c7d60"),road?"#555f63":"#3b694f");if(road){g.strokeStyle="#d6bc55";g.setLineDash([5,7]);g.beginPath();g.moveTo(p.x-TW/3,p.y);g.lineTo(p.x+TW/3,p.y);g.stroke();g.setLineDash([])}}
 function building(b){let p=iso(b.x,b.y),rx=b.w*TW/2,ry=b.w*TH/2,lx=b.h*TW/2,ly=b.h*TH/2,z=b.z,A={x:p.x,y:p.y-z},B={x:p.x+rx,y:p.y+ry-z},C={x:p.x+rx-lx,y:p.y+ry+ly-z},D1={x:p.x-lx,y:p.y+ly-z};poly([A,B,C,D1],b.c[2],"#8bc4d3");poly([B,{x:B.x,y:B.y+z},{x:C.x,y:C.y+z},C],b.c[0]);poly([C,{x:C.x,y:C.y+z},{x:D1.x,y:D1.y+z},D1],b.c[1]);for(let q=0;q<3;q++){g.fillStyle="#70d2e7";g.fillRect(C.x+8+q*18,C.y+18,11,16)}g.fillStyle=b.n==="ZIEKENHUIS"?"#162329":"#f4f5f5";g.font="bold 9px sans-serif";g.textAlign="center";g.fillText(b.n,p.x+(rx-lx)/2,p.y+(ry+ly)/2+10)}
 function poly(a,c,s){g.beginPath();g.moveTo(a[0].x,a[0].y);a.slice(1).forEach(p=>g.lineTo(p.x,p.y));g.closePath();g.fillStyle=c;g.fill();g.strokeStyle=s;g.stroke()}
 function tree(i,j){let p=iso(i,j);g.fillStyle="#5a3924";g.fillRect(p.x-3,p.y-22,6,22);g.fillStyle="#1f6d3c";g.beginPath();g.arc(p.x,p.y-29,14,0,7);g.fill();g.fillStyle="#3e9958";g.beginPath();g.arc(p.x-5,p.y-34,8,0,7);g.fill()}
 function avatar(o,n,you){let p=iso(o.x,o.y),bob=Math.sin(time*.012+(o.x||0))*.8;g.fillStyle="#0007";g.beginPath();g.ellipse(p.x,p.y+5,9,4,0,0,7);g.fill();g.fillStyle=you?"#d5a82e":"#376f99";g.fillRect(p.x-6,p.y-23+bob,12,18);g.fillStyle="#222";g.fillRect(p.x-6,p.y-5,5,9);g.fillRect(p.x+1,p.y-5,5,9);g.fillStyle="#d89c75";g.fillRect(p.x-6,p.y-32+bob,12,10);g.fillStyle="#24201e";g.fillRect(p.x-6,p.y-34+bob,12,4);g.fillStyle="#0b1119df";g.fillRect(p.x-23,p.y-48,46,12);g.fillStyle="#fff";g.font="8px sans-serif";g.textAlign="center";g.fillText(n,p.x,p.y-39)}
 function car(a,b,dir,col){let p=iso(a,b);g.save();g.translate(p.x,p.y-6);g.fillStyle=col;g.beginPath();g.moveTo(-15,0);g.lineTo(-9,-9);g.lineTo(8,-9);g.lineTo(15,0);g.lineTo(11,7);g.lineTo(-12,7);g.closePath();g.fill();g.fillStyle="#9ad7e5";g.fillRect(-7,-7,12,5);g.fillStyle="#111";g.beginPath();g.arc(-9,6,4,0,7);g.arc(9,6,4,0,7);g.fill();g.restore()}
 function draw(){time++;g.clearRect(0,0,W,H);let sky=g.createLinearGradient(0,0,0,H);sky.addColorStop(0,"#102438");sky.addColorStop(.22,"#326273");sky.addColorStop(.221,"#47745b");sky.addColorStop(1,"#1f4236");g.fillStyle=sky;g.fillRect(0,0,W,H);
 for(let s=0;s<S*2;s++)for(let i=0;i<S;i++){let j=s-i;if(j>=0&&j<S)tile(i,j)}
 [[6,6],[7,17],[18,7],[19,18],[4,11],[14,20],[20,13]].forEach(t=>tree(t[0],t[1]));
 bs.slice().sort((a,b)=>a.x+a.y-b.x-b.y).forEach(building);
 let z=(time*.025)%26;car(z-1,11,0,"#d4a72e");car(12,(z+8)%26-1,1,"#3d84b2");car((z+14)%26-1,12,0,"#a9454b");
 [{x:8+Math.sin(time/90)*1.5,y:9,n:"Rico"},{x:15,y:13+Math.sin(time/110)*1.8,n:"Luna"},{x:6,y:16+Math.cos(time/100)*1.4,n:"Vince"}].forEach(o=>avatar(o,o.n,false));
 others.forEach(o=>avatar(o,o.username,false));avatar(me,state.name||"RAMZY",true);requestAnimationFrame(draw)}
 function walk(){let dx=me.tx-me.x,dy=me.ty-me.y,d=Math.hypot(dx,dy);if(d>.05){me.x+=dx/d*.065;me.y+=dy/d*.065}requestAnimationFrame(walk)}
 cv.addEventListener("click",e=>{let r=cv.getBoundingClientRect(),q=cam(),sx=e.clientX-r.left-q.x,sy=e.clientY-r.top-q.y,gx=sy/TH+sx/TW,gy=sy/TH-sx/TW;for(let b of bs)if(gx>=b.x&&gx<=b.x+b.w&&gy>=b.y&&gy<=b.y+b.h){worldV2Open(b.go);return}me.tx=Math.max(.5,Math.min(S-1,gx));me.ty=Math.max(.5,Math.min(S-1,gy))});
 async function sync(){try{await fetch("/api/world/position",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({x:me.x/S*100,y:me.y/S*100})});let r=await fetch("/api/world/players"),d=await r.json();others=(d.players||[]).filter(v=>String(v.user_id)!==String(d.selfId)).map(v=>({x:+v.pos_x/100*S,y:+v.pos_y/100*S,username:v.username}))}catch(e){}}
 resize();walk();draw();sync();window._worldSync&&clearInterval(window._worldSync);window._worldSync=setInterval(sync,1200)
}

/* ===== WORLD V6 DENSE ISOMETRIC DISTRICT ===== */
async function showMyCity(){
 openPanel("🏙️ WEST-VLAMMERS V6","<p>V6 laden...</p>");
 try{let r=await fetch("/api/my-city");if(!r.ok)throw Error("Wereld laden mislukt");
 openPanel("🏙️ WEST-VLAMMERS V6",`<div class="v6game"><div class="v6head"><b>WEST-VLAMMERS</b><span>● ONLINE</span></div><canvas id="v6c"></canvas><div class="v6help">Tik om te lopen · deuren openen locaties</div></div>`);setupV6()}catch(e){openPanel("WORLD V6","<p>"+escapeHtml(e.message)+"</p>")}
}
function setupV6(){
 const C=$("v6c"),G=C.getContext("2d"),R=devicePixelRatio||1,TW=56,TH=28,N=28;let W,H,t=0,me={x:13,y:14,tx:13,ty:14},others=[];
 const B=[{x:3,y:3,w:4,h:4,z:78,n:"MAFFIA HQ",go:"missions",c:"#273746"},{x:10,y:2,w:4,h:4,z:68,n:"NIGHT CLUB",go:"chat",c:"#62316e"},{x:18,y:3,w:5,h:4,z:100,n:"APPARTEMENTEN",go:"properties",c:"#426b80"},{x:3,y:17,w:5,h:4,z:88,n:"ZIEKENHUIS",go:"hospital",c:"#b7cfd2"},{x:18,y:17,w:4,h:4,z:72,n:"POLITIE",go:"players",c:"#315c83"},{x:11,y:20,w:5,h:3,z:55,n:"GARAGE",go:"garage",c:"#514052"},{x:22,y:10,w:3,h:3,z:58,n:"CASINO",go:"missions",c:"#764329"}];
 function size(){let q=C.parentElement.getBoundingClientRect();W=q.width;H=Math.max(590,Math.min(730,innerHeight*.72));C.style.height=H+"px";C.width=W*R;C.height=H*R;G.setTransform(R,0,0,R,0,0)}
 const raw=(a,b)=>({x:(a-b)*TW/2,y:(a+b)*TH/2}),camera=()=>{let p=raw(me.x,me.y);return{x:W/2-p.x,y:H*.57-p.y}},iso=(a,b)=>{let p=raw(a,b),q=camera();return{x:p.x+q.x,y:p.y+q.y}};
 function path(a,c,s){G.beginPath();G.moveTo(a[0].x,a[0].y);a.slice(1).forEach(p=>G.lineTo(p.x,p.y));G.closePath();G.fillStyle=c;G.fill();if(s){G.strokeStyle=s;G.stroke()}}
 function tile(i,j){let p=iso(i,j),road=i===13||i===14||j===13||j===14,walk=i===12||i===15||j===12||j===15;path([{x:p.x,y:p.y-TH/2},{x:p.x+TW/2,y:p.y},{x:p.x,y:p.y+TH/2},{x:p.x-TW/2,y:p.y}],road?"#333b41":walk?"#9b9b8e":((i+j)%2?"#47785b":"#4e8061"),road?"#596064":"#41694f");if(road){G.strokeStyle="#dbc55e";G.setLineDash([5,7]);G.beginPath();G.moveTo(p.x-TW*.3,p.y);G.lineTo(p.x+TW*.3,p.y);G.stroke();G.setLineDash([])}}
 function building(b){let p=iso(b.x,b.y),rx=b.w*TW/2,ry=b.w*TH/2,lx=b.h*TW/2,ly=b.h*TH/2,z=b.z,A={x:p.x,y:p.y-z},D={x:p.x-lx,y:p.y+ly-z},Q={x:p.x+rx-lx,y:p.y+ry+ly-z},E={x:p.x+rx,y:p.y+ry-z};path([A,E,Q,D],light(b.c,25),"#87b9c5");path([E,{x:E.x,y:E.y+z},{x:Q.x,y:Q.y+z},Q],b.c);path([Q,{x:Q.x,y:Q.y+z},{x:D.x,y:D.y+z},D],light(b.c,-22));
 for(let row=0;row<2;row++)for(let col=0;col<3;col++){G.fillStyle="#69cce3";G.fillRect(Q.x+8+col*15,Q.y+13+row*24,9,13)}
 G.fillStyle="#171c21";G.fillRect(Q.x+23,Q.y+z-24,15,24);G.fillStyle=b.n==="ZIEKENHUIS"?"#182126":"#fff";G.font="bold 8px sans-serif";G.textAlign="center";G.fillText(b.n,p.x+(rx-lx)/2,p.y+(ry+ly)/2+10)}
 function light(hex,n){let v=parseInt(hex.slice(1),16),r=Math.max(0,Math.min(255,(v>>16)+n)),g=Math.max(0,Math.min(255,((v>>8)&255)+n)),b=Math.max(0,Math.min(255,(v&255)+n));return"#"+[r,g,b].map(x=>x.toString(16).padStart(2,"0")).join("")}
 function tree(a,b){let p=iso(a,b);G.fillStyle="#5d3b25";G.fillRect(p.x-3,p.y-18,6,20);G.fillStyle="#246c3d";G.beginPath();G.arc(p.x,p.y-27,13,0,7);G.fill();G.fillStyle="#48a35f";G.beginPath();G.arc(p.x-5,p.y-32,7,0,7);G.fill()}
 function lamp(a,b){let p=iso(a,b);G.strokeStyle="#20272b";G.lineWidth=3;G.beginPath();G.moveTo(p.x,p.y);G.lineTo(p.x,p.y-30);G.stroke();G.fillStyle="#ffe58a";G.fillRect(p.x-4,p.y-34,8,6)}
 function human(o,n,you){let p=iso(o.x,o.y),walk=Math.sin(t*.18)*2;G.fillStyle="#0007";G.beginPath();G.ellipse(p.x,p.y+4,8,3,0,0,7);G.fill();G.fillStyle="#25282c";G.fillRect(p.x-6,p.y-7,4,10+walk);G.fillRect(p.x+2,p.y-7,4,10-walk);G.fillStyle=you?"#d6aa2e":"#397aa5";G.fillRect(p.x-7,p.y-26,14,19);G.fillStyle="#d89d77";G.fillRect(p.x-6,p.y-36,12,11);G.fillStyle="#28201d";G.fillRect(p.x-6,p.y-38,12,4);G.fillStyle="#091018e8";G.fillRect(p.x-24,p.y-51,48,12);G.fillStyle="#fff";G.font="8px sans-serif";G.textAlign="center";G.fillText(n,p.x,p.y-42)}
 function car(a,b,c){let p=iso(a,b);G.fillStyle=c;path([{x:p.x-13,y:p.y},{x:p.x-8,y:p.y-8},{x:p.x+7,y:p.y-8},{x:p.x+14,y:p.y},{x:p.x+10,y:p.y+6},{x:p.x-11,y:p.y+6}],c);G.fillStyle="#9bd6e3";G.fillRect(p.x-6,p.y-7,11,5);G.fillStyle="#111";G.beginPath();G.arc(p.x-8,p.y+6,3,0,7);G.arc(p.x+8,p.y+6,3,0,7);G.fill()}
 function occupied(x,y){return B.some(b=>x>b.x-.3&&x<b.x+b.w+.3&&y>b.y-.3&&y<b.y+b.h+.3)}
 function draw(){t++;G.clearRect(0,0,W,H);let q=G.createLinearGradient(0,0,0,H);q.addColorStop(0,"#173247");q.addColorStop(.18,"#427b75");q.addColorStop(.181,"#315e49");q.addColorStop(1,"#17382e");G.fillStyle=q;G.fillRect(0,0,W,H);for(let s=0;s<N*2;s++)for(let i=0;i<N;i++){let j=s-i;if(j>=0&&j<N)tile(i,j)}
 [[7,7],[8,18],[20,8],[21,20],[5,13],[17,24],[24,15],[9,23],[23,6]].forEach(v=>tree(...v));[[12,8],[15,9],[12,18],[15,19],[8,12],[20,15]].forEach(v=>lamp(...v));B.slice().sort((a,b)=>a.x+a.y-b.x-b.y).forEach(building);
 let z=(t*.035)%30;car(z-1,13,"#d4a52d");car(14,(z+9)%30-1,"#397fac");car((z+16)%30-1,14,"#a54b51");
 [{x:9+Math.sin(t/100)*1.7,y:10,n:"Rico"},{x:17,y:11+Math.cos(t/120)*1.8,n:"Luna"},{x:8,y:18+Math.sin(t/130)*1.5,n:"Vince"}].forEach(o=>human(o,o.n,false));others.forEach(o=>human(o,o.username,false));human(me,state.name||"RAMZY",true);requestAnimationFrame(draw)}
 function move(){let dx=me.tx-me.x,dy=me.ty-me.y,d=Math.hypot(dx,dy);if(d>.06){let nx=me.x+dx/d*.07,ny=me.y+dy/d*.07;if(!occupied(nx,ny)){me.x=nx;me.y=ny}else{me.tx=me.x;me.ty=me.y}}requestAnimationFrame(move)}
 C.onclick=e=>{let r=C.getBoundingClientRect(),q=camera(),sx=e.clientX-r.left-q.x,sy=e.clientY-r.top-q.y,gx=sy/TH+sx/TW,gy=sy/TH-sx/TW;for(let b of B)if(gx>=b.x&&gx<=b.x+b.w&&gy>=b.y&&gy<=b.y+b.h){worldV2Open(b.go);return}if(!occupied(gx,gy)){me.tx=Math.max(.5,Math.min(N-1,gx));me.ty=Math.max(.5,Math.min(N-1,gy))}};
 async function sync(){try{await fetch("/api/world/position",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({x:me.x/N*100,y:me.y/N*100})});let r=await fetch("/api/world/players"),d=await r.json();others=(d.players||[]).filter(v=>String(v.user_id)!==String(d.selfId)).map(v=>({x:+v.pos_x/100*N,y:+v.pos_y/100*N,username:v.username}))}catch(e){}}
 size();draw();move();sync();window._worldSync&&clearInterval(window._worldSync);window._worldSync=setInterval(sync,1200)
}

/* ===== WORLD V7 SPRITE DISTRICT ===== */
async function showMyCity(){
 openPanel("🏙️ WEST-VLAMMERS V7","<p>Nieuwe wijk laden...</p>");
 try{let r=await fetch("/api/my-city");if(!r.ok)throw Error("Wereld laden mislukt");
 openPanel("🏙️ WEST-VLAMMERS V7",`<div class="v7game"><div class="v7bar"><b>WEST-VLAMMERS CITY</b><span>● MULTIPLAYER</span></div><div id="v7world" class="v7world"><div class="v7map">
 <div class="v7road v7rh"></div><div class="v7road v7rv"></div><div class="v7walk w1"></div><div class="v7walk w2"></div>
 <button class="v7building hq" data-go="missions"><span class="sign">MAFFIA HQ</span><i class="door"></i></button>
 <button class="v7building club" data-go="chat"><span class="sign">NIGHT CLUB</span><i class="door"></i></button>
 <button class="v7building flats" data-go="properties"><span class="sign">APPARTEMENTEN</span><i class="door"></i></button>
 <button class="v7building hospital" data-go="hospital"><span class="sign">✚ ZIEKENHUIS</span><i class="door"></i></button>
 <button class="v7building police" data-go="players"><span class="sign">POLITIE</span><i class="door"></i></button>
 <button class="v7building garage" data-go="garage"><span class="sign">GARAGE</span><i class="door"></i></button>
 <div class="v7tree t1"></div><div class="v7tree t2"></div><div class="v7tree t3"></div><div class="v7tree t4"></div><div class="v7bench"></div>
 <div class="v7lamp l1"></div><div class="v7lamp l2"></div><div class="v7lamp l3"></div>
 <div class="v7car taxi"><i></i></div><div class="v7car blue"><i></i></div>
 <div class="v7human npc n1"><i class="head"></i><i class="body"></i><i class="leg a"></i><i class="leg b"></i><b>Rico</b></div>
 <div class="v7human npc n2"><i class="head"></i><i class="body"></i><i class="leg a"></i><i class="leg b"></i><b>Luna</b></div>
 <div id="v7me" class="v7human me"><i class="head"></i><i class="body"></i><i class="leg a"></i><i class="leg b"></i><b>${escapeHtml(state.name||"RAMZY")}</b><em>JIJ</em></div>
 </div></div><div class="v7help">Tik op de grond om te lopen · tik op een gebouw om binnen te gaan</div></div>`);setupV7()}catch(e){openPanel("WORLD V7","<p>"+escapeHtml(e.message)+"</p>")}
}
function setupV7(){
 const view=$("v7world"),map=view&&view.querySelector(".v7map"),me=$("v7me");if(!view||!map||!me)return;let p={x:50,y:55},target=null;
 try{let q=JSON.parse(localStorage.getItem("v7pos")||"null");if(q)p=q}catch(e){}
 const blocks=[{x:8,y:7,w:23,h:20},{x:67,y:7,w:24,h:19},{x:5,y:66,w:25,h:22},{x:68,y:65,w:26,h:23},{x:38,y:70,w:24,h:18},{x:72,y:35,w:20,h:19}];
 const blocked=(x,y)=>blocks.some(b=>x>b.x&&x<b.x+b.w&&y>b.y&&y<b.y+b.h);
 const draw=()=>{me.style.left=p.x+"%";me.style.top=p.y+"%";map.style.transform="translate("+(50-p.x)*2.2+"px,"+(55-p.y)*1.5+"px)"};
 const walk=()=>{if(!target)return;let dx=target.x-p.x,dy=target.y-p.y,d=Math.hypot(dx,dy);if(d<.5){target=null;localStorage.setItem("v7pos",JSON.stringify(p));return}let nx=p.x+dx/d*.42,ny=p.y+dy/d*.42;if(blocked(nx,ny)){target=null;return}p.x=nx;p.y=ny;me.classList.add("walking");draw();requestAnimationFrame(walk)};
 view.onclick=e=>{let b=e.target.closest(".v7building");if(b){worldV2Open(b.dataset.go);return}let r=view.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*100,y=(e.clientY-r.top)/r.height*100;if(!blocked(x,y)){target={x,y};requestAnimationFrame(walk)}};
 async function sync(){try{await fetch("/api/world/position",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(p)});let r=await fetch("/api/world/players"),d=await r.json(),alive=new Set;for(let q of d.players||[]){if(String(q.user_id)===String(d.selfId))continue;let id="v7u"+q.user_id;alive.add(id);let el=$(id);if(!el){el=document.createElement("div");el.id=id;el.className="v7human other";el.innerHTML='<i class="head"></i><i class="body"></i><i class="leg a"></i><i class="leg b"></i><b></b>';map.appendChild(el)}el.style.left=q.pos_x+"%";el.style.top=q.pos_y+"%";el.querySelector("b").textContent=q.username}map.querySelectorAll(".other").forEach(e=>{if(!alive.has(e.id))e.remove()})}catch(e){}}
 draw();sync();window._worldSync&&clearInterval(window._worldSync);window._worldSync=setInterval(sync,1200)
}
